use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's `HTTPClient` handle is scoped to. A request outside this
/// set is a trap at the boundary (not a value), so we refuse it here first and
/// record it as a failure instead of letting it abort the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Conservative check: only plain `scheme://host[:digits]/...` URLs whose host
/// exactly matches the allowlist pass. Anything ambiguous (userinfo, IPv6
/// literals, percent-encoding, backslashes) is refused, so this check cannot
/// accept a URL that the host's own parser would read differently.
fn permitted_host(url: &str) -> bool {
    let rest = match url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))
    {
        Some(r) => r,
        None => return false,
    };

    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    if authority.contains(['@', '[', ']', '%', '\\']) {
        return false;
    }

    let (host, port) = match authority.split_once(':') {
        Some((h, p)) => (h, Some(p)),
        None => (authority, None),
    };

    if let Some(p) = port {
        if p.is_empty() || !p.bytes().all(|b| b.is_ascii_digit()) {
            return false;
        }
    }

    ALLOWED_HOSTS
        .iter()
        .any(|allowed| host.eq_ignore_ascii_case(allowed))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !permitted_host(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host outside node allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures (timeout, error status,
            // oversize body) as a value, so one dead feed does not fail the run.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
